    mounts = []
    for volume in volumes:
        if is_darwin(platform):
            if volume.get("skip_darwin"):
                continue
            mounts.append("%s:%s" % (volume["path"], volume["container_path"]))
        else:
            if volume.get("skip_linux"):
                continue
            mounts.append("%s:%s" % (volume["name"], volume["container_path"]))
    return mounts


