LABEL_VENDOR = "org.label-schema.vendor=%s" % PROG
LABEL_PROJECT = "io.%s.project" % PROG
COMPOSE_BASE_FILES = ("docker-compose.yml", "docker-compose.yaml", "compose.yml", "compose.yaml")
